import React, { useState, useEffect } from "react";
import "./Seo.css";
import { useLocation } from "react-router-dom";
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import { faFileLines, faClosedCaptioning, faSearch, faImage } from "@fortawesome/free-solid-svg-icons";

function SEO({ videoThumbnail }) {
  const location = useLocation(); // Get the location object
  const { message, seo_data } = location.state || {}; // Extract message and seo_data from location.state

  const [activeTab, setActiveTab] = useState("Keywords");
  const [currentSeoData, setCurrentSeoData] = useState("");
  const [seoMessage, setSeoMessage] = useState(message || "No SEO data received.");

  useEffect(() => {
    console.log("Received seoData:", seo_data);
  }, [seo_data]);

  // Update the displayed SEO data dynamically based on the active tab
  useEffect(() => {
    if (seo_data) {
      switch (activeTab) {
        case "Keywords":
          setCurrentSeoData(
            seo_data.keywords && seo_data.keywords.length > 0
              ? seo_data.keywords.join(", ")
              : "No keywords available."
          );
          break;
        case "Description":
          setCurrentSeoData(seo_data.description || "No description available.");
          break;
        case "Title":
          setCurrentSeoData(seo_data.title || "No title available.");
          break;
        case "Tags":
          setCurrentSeoData(
            seo_data.tags && seo_data.tags.length > 0
              ? seo_data.tags.join(", ")
              : "No tags available."
          );
          break;
        default:
          setCurrentSeoData("No data available for this section.");
      }
    } else {
      setCurrentSeoData("No SEO data provided.");
    }
  }, [activeTab, seo_data]);

  return (
    <div className="seo-app">
      {/* Header Section */}
      <header className="header">
        <h1 className="logo">
          <span className="bold">Channel-</span>
          <span className="highlight">IQ</span>
        </h1>
        <nav className="nav">
          <a href="#clipper">Clipper</a>
          <a href="#seo">SEO</a>
          <a href="#thumbnail">Thumbnail</a>
          <a href="#pricing">Pricing</a>
          <button className="sign-in">Sign in</button>
          <button className="sign-up">Sign up</button>
        </nav>
      </header>

      {/* Main Content Section */}
      <main className="main-content">
        {/* Navigation to Clipper */}
        <button className="clipper-btn">Go to Clipper</button>

        {/* Clip Section */}
        <div className="clip-section">
          {/* Image Preview */}
          <div className="image-preview">
            <img
              src={videoThumbnail || "https://via.placeholder.com/300x300"}
              alt="Video Thumbnail"
              className="preview-image"
            />
          </div>

          {/* Clip Customization */}
          <div className="customize-clip">
            {/* SEO Data Display */}
            <div className="seo-data">
              <div className="seo-box">
                <h2>Keywords</h2>
                <p>{currentSeoData}</p>
              </div>
              <div className="seo-box">
                <h2>Description</h2>
                <p>{currentSeoData}</p>
              </div>
              <div className="seo-box">
                <h2>Title</h2>
                <p>{currentSeoData}</p>
              </div>
              <div className="seo-box">
                <h2>Tags</h2>
                <p>{currentSeoData}</p>
              </div>
            </div>
          </div>
        </div>
      </main>
    </div>
  );
}

export default SEO;
